// Shared constants and SDK message shapes for the CLI simulator: the recorded
// catalog, simulated latencies, the CLI's fixed notice texts and the shapes of
// usage blocks, recorded from the pinned CLI 2.1.237.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { SLOW_CHUNKS } from './prompt-markers.mjs'

const here = path.dirname(fileURLToPath(import.meta.url))

/** The pinned CLI's command, model and agent catalog and the static fields of system/init. */
export const CATALOG = JSON.parse(fs.readFileSync(path.join(here, 'catalog.json'), 'utf8'))

// Simulated latencies (ms at time scale 1), close to what the pinned CLI shows
// against a loopback provider. Only their order matters to the traces.
export const T = {
  boot: 600,
  queuedToStarted: 4,
  startedToInit: 20,
  initToStatus: 3,
  requestLatency: 50,
  toolOverhead: 20,
  afterResult: 1,
  abortSettle: 3,
  localCommand: 6,
  compaction: 25,
  taskPromotion: 3000,
  heartbeat: 30_000,
  subagent: 2000,
  agentLaunch: 50,
}

export const TOOL_REJECTED = "The user doesn't want to proceed with this tool use. The tool use was rejected (eg. if it was a file edit, the new_string was NOT written to the file). STOP what you are doing and wait for the user to tell you how to proceed."
export const INTERRUPTED = '[Request interrupted by user]'
export const INTERRUPTED_FOR_TOOL = '[Request interrupted by user for tool use]'
export const CAVEAT = '<local-command-caveat>Caveat: The messages below were generated by the user while running local commands. DO NOT respond to these messages or otherwise consider them in your response unless the user explicitly asks you to.</local-command-caveat>'
export const READ_ONLY_COMMANDS = new Set(['sleep', 'ls', 'cat', 'echo', 'pwd', 'true', 'grep', 'head', 'tail', 'wc'])
export const FAKE_MODEL = 'claude-sonnet-4-5-20250929'
export const SUBAGENT_TEXT = Array.from({ length: SLOW_CHUNKS }, (_, i) => `chunk${i} `).join('')

export const usage = (input = 1, output = 1) => ({
  input_tokens: input,
  cache_creation_input_tokens: 0,
  cache_read_input_tokens: 0,
  output_tokens: output,
  output_tokens_details: { thinking_tokens: 0 },
  server_tool_use: { web_search_requests: 0, web_fetch_requests: 0 },
  service_tier: 'standard',
  cache_creation: { ephemeral_1h_input_tokens: 0, ephemeral_5m_input_tokens: 0 },
  inference_geo: '',
  iterations: [],
  speed: 'standard',
})

export const isUuid = (value) => typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value)

export function textOf(content) {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  return content.filter((block) => block?.type === 'text').map((block) => block.text ?? '').join('\n')
}

export function commandLine(name, args = '') {
  return `<command-name>/${name}</command-name>\n            <command-message>${name}</command-message>\n            <command-args>${args}</command-args>`
}
